// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract DeliveryTrackingContract {
    address public owner;

    enum DeliveryStatus { Pending, InTransit, Delivered }

    struct Tracking {
        uint256 trackingId;
        uint256 orderId;
        address deliveryProvider;
        DeliveryStatus status;
        // TODO: add createdAt timestamp later
    }

    mapping(uint256 => Tracking) public trackings;
    uint256 public trackingCount;

    event TrackingCreated(uint256 trackingId, uint256 orderId, address deliveryProvider);
    event TrackingStatusUpdated(uint256 trackingId, DeliveryStatus status);

    constructor() {
        owner = msg.sender;
    }

    // only the delivery provider who created this specific tracking
    modifier onlyDeliveryProvider(uint256 _trackingId) {
        require(msg.sender == trackings[_trackingId].deliveryProvider, "Only the delivery provider can do this");
        _;
    }

    // delivery provider registers a new tracking record against an order
    function createTracking(uint256 _orderId) public {
        trackingCount++;
        trackings[trackingCount] = Tracking(
            trackingCount,
            _orderId,
            msg.sender,
            DeliveryStatus.Pending
        );
        emit TrackingCreated(trackingCount, _orderId, msg.sender);
    }

    // delivery provider walks the parcel through InTransit -> Delivered
    function updateTrackingStatus(uint256 _trackingId, DeliveryStatus _status)
        public
        onlyDeliveryProvider(_trackingId)
    {
        require(_trackingId > 0 && _trackingId <= trackingCount, "Invalid tracking ID");
        trackings[_trackingId].status = _status;
        emit TrackingStatusUpdated(_trackingId, _status);
    }

    function getTrackingDetails(uint256 _trackingId)
        public
        view
        returns (
            uint256 orderId,
            address deliveryProvider,
            DeliveryStatus status
        )
    {
        require(_trackingId > 0 && _trackingId <= trackingCount, "Invalid tracking ID");
        Tracking storage t = trackings[_trackingId];
        return (t.orderId, t.deliveryProvider, t.status);
    }
}

